<template><div class="page"><h2>健康评估 · {{level==='single'?'单机级':'系统级'}}</h2><p class="note">单机级 CDPCA-GA 特征融合 / AE-GMM 数据驱动;系统级 GCN + RBD 系统健康评估。</p><el-tabs v-model="level"><el-tab-pane label="单机级" name="single"/><el-tab-pane label="系统级" name="system"/></el-tabs><el-select v-if="level==='single'" v-model="id" placeholder="选择数据集" filterable><el-option v-for="d in data" :key="d.id" :label="d.name" :value="d.id"/></el-select><template v-else><el-select v-model="system" placeholder="选择系统/单机" @change="systemDatasetIds=[]"><el-option v-for="x in systems" :key="x" :label="x" :value="x"/></el-select><el-select v-model="systemDatasetIds" multiple collapse-tags filterable placeholder="选择该系统的数据集"><el-option v-for="d in systemDatasets" :key="d.id" :label="d.name" :value="d.id"/></el-select></template><el-select v-model="algorithm"><template v-if="level==='single'"><el-option label="CDPCA-GA 特征融合" value="cdpca_ga"/><el-option label="AE-GMM 数据驱动" value="ae_gmm"/></template><el-option v-else label="GCN + RBD 系统健康评估" value="gcn_rbd"/></el-select><el-button type="primary" :disabled="level==='single'?!id:!systemDatasetIds.length" :loading="loading" @click="run">运行评估</el-button><el-card v-if="result" class="report"><h3>{{result.algorithm}} 评估报告</h3><el-descriptions border :column="3"><el-descriptions-item label="评估层级">{{levelLabels[result.level]||result.level}}</el-descriptions-item><el-descriptions-item label="当前健康指数">{{Number(result.health_index).toFixed(4)}}</el-descriptions-item><el-descriptions-item label="健康等级">{{grade}}</el-descriptions-item><el-descriptions-item label="样本数">{{result.hi_sequence?.length||0}}</el-descriptions-item></el-descriptions><div class="chart"><svg viewBox="0 0 800 260" preserveAspectRatio="none"><g class="grid"><line v-for="tick in yTicks" :key="tick" x1="58" :y1="y(tick)" x2="780" :y2="y(tick)"/><text v-for="tick in yTicks" :key="`label-${tick}`" x="8" :y="y(tick)+4">{{tick.toFixed(2)}}</text></g><line class="axis" x1="58" y1="220" x2="780" y2="220"/><line class="axis" x1="58" y1="20" x2="58" y2="220"/><polyline :points="points" fill="none" stroke="#409eff" stroke-width="3"/><text class="axis-label" x="395" y="252">样本 / 时间</text><text class="axis-label" transform="translate(16,160) rotate(-90)">健康指数 HI</text></svg></div></el-card></div></template>
<script setup>import{ref,computed,onMounted,watch}from'vue';const levelLabels={single:'单机级',component:'单机级',system:'系统级'},data=ref([]),level=ref('single'),id=ref(),system=ref(),systemDatasetIds=ref([]),algorithm=ref('cdpca_ga'),result=ref(),loading=ref(false),yTicks=[0,0.25,0.5,0.75,1];watch(level,value=>{algorithm.value=value==='system'?'gcn_rbd':'cdpca_ga';result.value=undefined});onMounted(async()=>{data.value=await(await fetch('/api/v1/datasets/')).json()});const systems=computed(()=>[...new Set(data.value.map(x=>x.system).filter(Boolean))]);const systemDatasets=computed(()=>data.value.filter(x=>x.system===system.value));const y=v=>220-Number(v)*200;const points=computed(()=>{const a=result.value?.hi_sequence||[];return a.map((v,i)=>`${58+i/(Math.max(a.length-1,1))*722},${y(Math.max(0,Math.min(1,Number(v))))}`).join(' ')});const grade=computed(()=>{const v=Number(result.value?.health_index);return v>=.8?'健康':v>=.5?'关注':'异常'});async function run(){loading.value=true;try{const p=level.value==='single'?{dataset_id:id.value,algorithm:algorithm.value}:{dataset_ids:systemDatasetIds.value,algorithm:'gcn_rbd',component_ids:systemDatasetIds.value.map(datasetId=>{const d=data.value.find(x=>x.id===datasetId);return d?.component||`dataset_${datasetId}`})};const r=await fetch('/api/v1/health-assessment/evaluate/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});const j=await r.json();if(!r.ok)throw Error(j.error||'评估失败');result.value=j.result||j}finally{loading.value=false}}</script><style scoped>.page{max-width:1100px}.note{color:#60728a}.el-select{width:280px;margin-right:12px}.report{margin-top:20px}.chart{height:260px;margin-top:20px;background:#f5f8fc}.chart svg{width:100%;height:100%}.grid line{stroke:#dbe5f0;stroke-width:1}.grid text{fill:#60728a;font-size:12px}.axis{stroke:#718198;stroke-width:1.5}.axis-label{fill:#51657d;font-size:12px}</style>
